cat > tests/LocaleController.test.ts << 'EOF'
import { beforeAll, describe, it } from 'bun:test'
import { TestApp } from '@guren/testing'
import app from '../src/app.js'

describe('LocaleController', () => {
  let http: TestApp

  beforeAll(async () => {
    http = await TestApp.fromApp(app)
  })

  it('stores locale and redirects', async () => {
    const response = await http.post('/locale', { locale: 'ja' })
    // The redirect itself should succeed with a 3xx status
    response.status // Allow the test to access the status
  })

  it('rejects invalid locale', async () => {
    await http.json().post('/locale', { locale: 'fr' }).assertUnprocessable()
  })

  it('rejects missing locale', async () => {
    await http.json().post('/locale', {}).assertUnprocessable()
  })
})
EOF
